ensureModule(SP:WaitForChild('StarterPlayerScripts'), 'ClientController', 'ModuleScript', 'local Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal UserInputService = game:GetService("UserInputService")\nlocal TweenService = game:GetService("TweenService")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\nlocal Remotes = ReplicatedStorage:WaitForChild("RemoteEvents")\n\nlocal player = Players.LocalPlayer\nlocal mouse = player:GetMouse()\n\nlocal Client = {}\nClient.__index = Client\n\nlocal interactionTarget = nil\nlocal interactionRange = 8\nlocal currentDoor = nil\nlocal wantedLabel = nil\nlocal cipherLabel = nil\n\nfunction Client:Init()\n	self:SetupInteraction()\n	self:SetupHUD()\n	self:SetupDoorInteraction()\n	self:SetupWantedDisplay()\nend\n\nfunction Client:SetupInteraction()\n	UserInputService.InputBegan:Connect(function(input, processed)\n		if processed then return end\n\n		if input.KeyCode == Enum.KeyCode.E then\n			self:HandleInteraction("E")\n		elseif input.KeyCode == Enum.KeyCode.F then\n			self:HandleInteraction("F")\n		end\n	end)\nend\n\nfunction Client:HandleInteraction(key)\n	local character = player.Character\n	if not character then return end\n\n	local rootPart = character:FindFirstChild("HumanoidRootPart")\n	if not rootPart then return end\n\n	local target = self:GetClosestInteractable(rootPart, interactionRange)\n	if not target then return end\n\n	local interactType = target:GetAttribute("InteractType")\n\n	if key == "E" then\n		if interactType == "Door" then\n			Remotes.OpenDoor:FireServer(target)\n		elseif interactType == "BriefcaseTarget" then\n			Remotes.UseBriefcase:FireServer(player)\n		elseif interactType == "PillAccept" then\n			Remotes.AcceptPill:FireServer()\n		elseif interactType == "DShop" then\n			self:OpenDShop()\n		elseif interactType == "Shield" then\n			Remotes.InteractShield:FireServer(target:GetAttribute("ShieldId"))\n		elseif interactType == "CameraDesk" then\n			self:OpenCameraSystem()\n		elseif interactType == "ManagerComputer" then\n			self:OpenManagerMenu()\n		end\n	elseif key == "F" then\n		if interactType == "SyringeTarget" then\n			Remotes.InjectSyringe:FireServer(player)\n		end\n	end\nend\n\nfunction Client:GetClosestInteractable(rootPart, range)\n	local closest = nil\n	local closestDist = range\n\n	for _, obj in ipairs(workspace:GetDescendants()) do\n		if obj:IsA("BasePart") and obj:GetAttribute("InteractType") then\n			local dist = (rootPart.Position - obj.Position).Magnitude\n			if dist < closestDist then\n				closestDist = dist\n				closest = obj\n			end\n		end\n	end\n\n	return closest\nend\n\nfunction Client:SetupHUD()\n	local screenGui = Instance.new("ScreenGui")\n	screenGui.Name = "GameHUD"\n	screenGui.ResetOnSpawn = false\n	screenGui.Parent = player.PlayerGui\n\n	cipherLabel = Instance.new("TextLabel")\n	cipherLabel.Name = "CipherDisplay"\n	cipherLabel.Size = UDim2.new(0, 200, 0, 40)\n	cipherLabel.Position = UDim2.new(0, 10, 1, -50)\n	cipherLabel.BackgroundColor3 = Color3.fromRGB(20, 20, 20)\n	cipherLabel.BackgroundTransparency = 0.3\n	cipherLabel.TextColor3 = Color3.fromRGB(200, 200, 200)\n	cipherLabel.Font = Enum.Font.GothamBold\n	cipherLabel.TextSize = 18\n	cipherLabel.Text = "Шифры: 0"\n	cipherLabel.Parent = screenGui\n\n	local corner = Instance.new("UICorner")\n	corner.CornerRadius = UDim.new(0, 8)\n	corner.Parent = cipherLabel\n\n	task.spawn(function()\n		while true do\n			task.wait(2)\n			local ok, ciphers = pcall(function()\n				return Remotes.GetCiphers:InvokeServer()\n			end)\n			if ok and ciphers and cipherLabel then\n				cipherLabel.Text = "Шифры: " .. tostring(ciphers)\n			end\n		end\n	end)\nend\n\nfunction Client:SetupWantedDisplay()\n	wantedLabel = Instance.new("TextLabel")\n	wantedLabel.Name = "WantedDisplay"\n	wantedLabel.Size = UDim2.new(0, 300, 0, 50)\n	wantedLabel.Position = UDim2.new(0.5, -150, 0, 10)\n	wantedLabel.BackgroundColor3 = Color3.fromRGB(150, 0, 0)\n	wantedLabel.BackgroundTransparency = 0.2\n	wantedLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n	wantedLabel.Font = Enum.Font.GothamBold\n	wantedLabel.TextSize = 24\n	wantedLabel.Text = "РОЗЫСК"\n	wantedLabel.Visible = false\n	wantedLabel.Parent = player.PlayerGui:WaitForChild("GameHUD")\n\n	local corner = Instance.new("UICorner")\n	corner.CornerRadius = UDim.new(0, 8)\n	corner.Parent = wantedLabel\n\n	player:GetAttributeChangedSignal("IsWanted"):Connect(function()\n		wantedLabel.Visible = player:GetAttribute("IsWanted") == true\n	end)\nend\n\nfunction Client:SetupDoorInteraction()\n	local prompt = Instance.new("ProximityPrompt")\n	prompt.ActionText = "Открыть"\n	prompt.ObjectText = "Дверь"\n	prompt.MaxActivationDistance = interactionRange\n	prompt.HoldDuration = 0\n	prompt.KeyboardKeyCode = Enum.KeyCode.E\n\n	workspace.DescendantAdded:Connect(function(obj)\n		if obj:IsA("Model") and obj:GetAttribute("DoorType") then\n			local primaryPart = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")\n			if primaryPart then\n				local doorPrompt = prompt:Clone()\n				doorPrompt.Parent = primaryPart\n				doorPrompt.Triggered:Connect(function()\n					Remotes.OpenDoor:FireServer(obj)\n				end)\n			end\n		end\n	end)\nend\n\nfunction Client:OpenDShop()\n	Remotes.BuyItem:FireServer("Medkit", 75)\nend\n\nfunction Client:OpenCameraSystem()\n	local cameras = Remotes.GetAllCameras and Remotes.GetAllCameras:InvokeServer() or {}\n	local currentCameraIndex = 1\n\n	local screenGui = Instance.new("ScreenGui")\n	screenGui.Name = "CameraSystem"\n	screenGui.Parent = player.PlayerGui\n\n	local frame = Instance.new("Frame")\n	frame.Size = UDim2.new(1, 0, 1, 0)\n	frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n	frame.BackgroundTransparency = 0.3\n	frame.Parent = screenGui\n\n	local closeButton = Instance.new("TextButton")\n	closeButton.Size = UDim2.new(0, 100, 0, 40)\n	closeButton.Position = UDim2.new(1, -110, 0, 10)\n	closeButton.BackgroundColor3 = Color3.fromRGB(150, 0, 0)\n	closeButton.TextColor3 = Color3.fromRGB(255, 255, 255)\n	closeButton.Text = "Закрыть"\n	closeButton.Font = Enum.Font.GothamBold\n	closeButton.TextSize = 16\n	closeButton.Parent = frame\n\n	local nextButton = Instance.new("TextButton")\n	nextButton.Size = UDim2.new(0, 60, 0, 40)\n	nextButton.Position = UDim2.new(1, -80, 0.5, -20)\n	nextButton.BackgroundColor3 = Color3.fromRGB(50, 50, 50)\n	nextButton.TextColor3 = Color3.fromRGB(255, 255, 255)\n	nextButton.Text = ">"\n	nextButton.Font = Enum.Font.GothamBold\n	nextButton.TextSize = 20\n	nextButton.Parent = frame\n\n	local prevButton = Instance.new("TextButton")\n	prevButton.Size = UDim2.new(0, 60, 0, 40)\n	prevButton.Position = UDim2.new(0, 20, 0.5, -20)\n	prevButton.BackgroundColor3 = Color3.fromRGB(50, 50, 50)\n	prevButton.TextColor3 = Color3.fromRGB(255, 255, 255)\n	prevButton.Text = "<"\n	prevButton.Font = Enum.Font.GothamBold\n	prevButton.TextSize = 20\n	prevButton.Parent = frame\n\n	closeButton.MouseButton1Click:Connect(function()\n		Remotes.DeactivateCamera:FireServer()\n		screenGui:Destroy()\n	end)\n\n	nextButton.MouseButton1Click:Connect(function()\n		if #cameras > 0 then\n			currentCameraIndex = currentCameraIndex % #cameras + 1\n			Remotes.ActivateCamera:FireServer(cameras[currentCameraIndex].id)\n		end\n	end)\n\n	prevButton.MouseButton1Click:Connect(function()\n		if #cameras > 0 then\n			currentCameraIndex = (currentCameraIndex - 2) % #cameras + 1\n			Remotes.ActivateCamera:FireServer(cameras[currentCameraIndex].id)\n		end\n	end)\nend\n\nfunction Client:OpenManagerMenu()\n	local screenGui = Instance.new("ScreenGui")\n	screenGui.Name = "ManagerMenu"\n	screenGui.Parent = player.PlayerGui\n\n	local frame = Instance.new("Frame")\n	frame.Size = UDim2.new(0.4, 0, 0.5, 0)\n	frame.Position = UDim2.new(0.3, 0, 0.25, 0)\n	frame.BackgroundColor3 = Color3.fromRGB(30, 30, 30)\n	frame.BorderSizePixel = 0\n	frame.Parent = screenGui\n\n	local corner = Instance.new("UICorner")\n	corner.CornerRadius = UDim.new(0, 12)\n	corner.Parent = frame\n\n	local layout = Instance.new("UIListLayout")\n	layout.Padding = UDim.new(0, 8)\n	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n	layout.VerticalAlignment = Enum.VerticalAlignment.Top\n	layout.SortOrder = Enum.SortOrder.LayoutOrder\n	layout.Parent = frame\n\n	local title = Instance.new("TextLabel")\n	title.Size = UDim2.new(1, 0, 0, 40)\n	title.BackgroundTransparency = 1\n	title.Text = "Панель менеджера"\n	title.TextColor3 = Color3.fromRGB(255, 255, 255)\n	title.Font = Enum.Font.GothamBold\n	title.TextSize = 20\n	title.LayoutOrder = 1\n	title.Parent = frame\n\n	local function createButton(text, order, callback)\n		local btn = Instance.new("TextButton")\n		btn.Size = UDim2.new(0.8, 0, 0, 40)\n		btn.BackgroundColor3 = Color3.fromRGB(50, 50, 50)\n		btn.TextColor3 = Color3.fromRGB(255, 255, 255)\n		btn.Text = text\n		btn.Font = Enum.Font.Gotham\n		btn.TextSize = 16\n		btn.LayoutOrder = order\n		btn.Parent = frame\n\n		local btnCorner = Instance.new("UICorner")\n		btnCorner.CornerRadius = UDim.new(0, 6)\n		btnCorner.Parent = btn\n\n		btn.MouseButton1Click:Connect(callback)\n\n		return btn\n	end\n\n	local function createInputDialog(titleText, callback)\n		local dialog = Instance.new("Frame")\n		dialog.Size = UDim2.new(0.3, 0, 0.3, 0)\n		dialog.Position = UDim2.new(0.35, 0, 0.35, 0)\n		dialog.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\n		dialog.BorderSizePixel = 0\n		dialog.Parent = screenGui\n\n		local dialogCorner = Instance.new("UICorner")\n		dialogCorner.CornerRadius = UDim.new(0, 8)\n		dialogCorner.Parent = dialog\n\n		local dialogTitle = Instance.new("TextLabel")\n		dialogTitle.Size = UDim2.new(1, 0, 0, 30)\n		dialogTitle.BackgroundTransparency = 1\n		dialogTitle.Text = titleText\n		dialogTitle.TextColor3 = Color3.fromRGB(255, 255, 255)\n		dialogTitle.Font = Enum.Font.GothamBold\n		dialogTitle.TextSize = 16\n		dialogTitle.Parent = dialog\n\n		local nameInput = Instance.new("TextBox")\n		nameInput.Size = UDim2.new(0.8, 0, 0, 30)\n		nameInput.Position = UDim2.new(0.1, 0, 0, 40)\n		nameInput.BackgroundColor3 = Color3.fromRGB(60, 60, 60)\n		nameInput.TextColor3 = Color3.fromRGB(255, 255, 255)\n		nameInput.PlaceholderText = "Ник игрока"\n		nameInput.Font = Enum.Font.Gotham\n		nameInput.TextSize = 14\n		nameInput.ClearTextOnFocus = false\n		nameInput.Parent = dialog\n\n		local reasonInput = Instance.new("TextBox")\n		reasonInput.Size = UDim2.new(0.8, 0, 0, 30)\n		reasonInput.Position = UDim2.new(0.1, 0, 0, 80)\n		reasonInput.BackgroundColor3 = Color3.fromRGB(60, 60, 60)\n		reasonInput.TextColor3 = Color3.fromRGB(255, 255, 255)\n		reasonInput.PlaceholderText = "Причина"\n		reasonInput.Font = Enum.Font.Gotham\n		reasonInput.TextSize = 14\n		reasonInput.ClearTextOnFocus = false\n		reasonInput.Parent = dialog\n\n		local confirmBtn = Instance.new("TextButton")\n		confirmBtn.Size = UDim2.new(0.8, 0, 0, 30)\n		confirmBtn.Position = UDim2.new(0.1, 0, 0, 120)\n		confirmBtn.BackgroundColor3 = Color3.fromRGB(0, 100, 0)\n		confirmBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\n		confirmBtn.Text = "Готово"\n		confirmBtn.Font = Enum.Font.GothamBold\n		confirmBtn.TextSize = 14\n		confirmBtn.Parent = dialog\n\n		local confirmCorner = Instance.new("UICorner")\n		confirmCorner.CornerRadius = UDim.new(0, 6)\n		confirmCorner.Parent = confirmBtn\n\n		confirmBtn.MouseButton1Click:Connect(function()\n			callback(nameInput.Text, reasonInput.Text)\n			dialog:Destroy()\n		end)\n	end\n\n	createButton("Уволить сотрудника", 2, function()\n		createInputDialog("Увольнение", function(name, reason)\n			Remotes.ManagerFire:FireServer(name, reason)\n		end)\n	end)\n\n	createButton("Объявить в розыск", 3, function()\n		createInputDialog("Розыск", function(name, reason)\n			Remotes.ManagerDeclareWanted:FireServer(name, reason, Config.WANTED_DURATION)\n		end)\n	end)\n\n	createButton("Выдать выговор", 4, function()\n		createInputDialog("Выговор", function(name, reason)\n			Remotes.ManagerWarning:FireServer(name, reason)\n		end)\n	end)\n\n	createButton("Выдать премию", 5, function()\n		local dialog = Instance.new("Frame")\n		dialog.Size = UDim2.new(0.3, 0, 0.3, 0)\n		dialog.Position = UDim2.new(0.35, 0, 0.35, 0)\n		dialog.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\n		dialog.BorderSizePixel = 0\n		dialog.Parent = screenGui\n\n		local dialogCorner = Instance.new("UICorner")\n		dialogCorner.CornerRadius = UDim.new(0, 8)\n		dialogCorner.Parent = dialog\n\n		local dialogTitle = Instance.new("TextLabel")\n		dialogTitle.Size = UDim2.new(1, 0, 0, 30)\n		dialogTitle.BackgroundTransparency = 1\n		dialogTitle.Text = "Премия"\n		dialogTitle.TextColor3 = Color3.fromRGB(255, 255, 255)\n		dialogTitle.Font = Enum.Font.GothamBold\n		dialogTitle.TextSize = 16\n		dialogTitle.Parent = dialog\n\n		local nameInput = Instance.new("TextBox")\n		nameInput.Size = UDim2.new(0.8, 0, 0, 30)\n		nameInput.Position = UDim2.new(0.1, 0, 0, 40)\n		nameInput.BackgroundColor3 = Color3.fromRGB(60, 60, 60)\n		nameInput.TextColor3 = Color3.fromRGB(255, 255, 255)\n		nameInput.PlaceholderText = "Ник игрока"\n		nameInput.Font = Enum.Font.Gotham\n		nameInput.TextSize = 14\n		nameInput.ClearTextOnFocus = false\n		nameInput.Parent = dialog\n\n		local amountInput = Instance.new("TextBox")\n		amountInput.Size = UDim2.new(0.8, 0, 0, 30)\n		amountInput.Position = UDim2.new(0.1, 0, 0, 80)\n		amountInput.BackgroundColor3 = Color3.fromRGB(60, 60, 60)\n		amountInput.TextColor3 = Color3.fromRGB(255, 255, 255)\n		amountInput.PlaceholderText = "Количество шифров"\n		amountInput.Font = Enum.Font.Gotham\n		amountInput.TextSize = 14\n		amountInput.ClearTextOnFocus = false\n		amountInput.Parent = dialog\n\n		local confirmBtn = Instance.new("TextButton")\n		confirmBtn.Size = UDim2.new(0.8, 0, 0, 30)\n		confirmBtn.Position = UDim2.new(0.1, 0, 0, 120)\n		confirmBtn.BackgroundColor3 = Color3.fromRGB(0, 100, 0)\n		confirmBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\n		confirmBtn.Text = "Выдать"\n		confirmBtn.Font = Enum.Font.GothamBold\n		confirmBtn.TextSize = 14\n		confirmBtn.Parent = dialog\n\n		local confirmCorner = Instance.new("UICorner")\n		confirmCorner.CornerRadius = UDim.new(0, 6)\n		confirmCorner.Parent = confirmBtn\n\n		confirmBtn.MouseButton1Click:Connect(function()\n			local amount = tonumber(amountInput.Text) or 0\n			Remotes.ManagerBonus:FireServer(nameInput.Text, amount, "Премия от менеджера")\n			dialog:Destroy()\n		end)\n	end)\n\n	local closeFrame = Instance.new("TextButton")\n	closeFrame.Size = UDim2.new(0.8, 0, 0, 35)\n	closeFrame.Position = UDim2.new(0.1, 0, 1, -45)\n	closeFrame.BackgroundColor3 = Color3.fromRGB(150, 0, 0)\n	closeFrame.TextColor3 = Color3.fromRGB(255, 255, 255)\n	closeFrame.Text = "Закрыть"\n	closeFrame.Font = Enum.Font.GothamBold\n	closeFrame.TextSize = 14\n	closeFrame.LayoutOrder = 6\n	closeFrame.Parent = frame\n\n	local closeCorner = Instance.new("UICorner")\n	closeCorner.CornerRadius = UDim.new(0, 6)\n	closeCorner.Parent = closeFrame\n\n	closeFrame.MouseButton1Click:Connect(function()\n		screenGui:Destroy()\n	end)\nend\n\nreturn Client\n')
ensureModule(SP:WaitForChild('StarterPlayerScripts'), 'WeaponClient', 'ModuleScript', 'local Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal UserInputService = game:GetService("UserInputService")\nlocal RunService = game:GetService("RunService")\nlocal TweenService = game:GetService("TweenService")\n\nlocal player = Players.LocalPlayer\nlocal camera = workspace.CurrentCamera\n\nlocal WeaponClient = {}\nWeaponClient.__index = WeaponClient\n\nlocal Remotes = nil\nlocal isAiming = false\nlocal defaultFOV = 70\nlocal adsFOV = 45\nlocal recoilOffset = Vector3.new()\nlocal currentSpread = 0\n\nlocal ammoGui = nil\nlocal ammoLabel = nil\nlocal reserveLabel = nil\nlocal crosshair = nil\nlocal firing = false\n\nlocal function isFirstPerson()\n	local character = player.Character\n	local head = character and character:FindFirstChild("Head")\n	if not head then return false end\n	return (camera.CFrame.Position - head.Position).Magnitude < 2\nend\n\nfunction WeaponClient:Init()\n	Remotes = ReplicatedStorage:WaitForChild("RemoteEvents")\n	self:SetupUI()\n	self:SetupInput()\n	self:SetupRenderStep()\nend\n\nfunction WeaponClient:SetupUI()\n	local screenGui = Instance.new("ScreenGui")\n	screenGui.Name = "WeaponHUD"\n	screenGui.ResetOnSpawn = false\n	screenGui.Parent = player.PlayerGui\n\n	crosshair = Instance.new("Frame")\n	crosshair.Name = "Crosshair"\n	crosshair.Size = UDim2.new(0, 20, 0, 20)\n	crosshair.AnchorPoint = Vector2.new(0.5, 0.5)\n	crosshair.Position = UDim2.new(0.5, 0, 0.5, 0)\n	crosshair.BackgroundTransparency = 1\n	crosshair.Parent = screenGui\n\n	local crossDot = Instance.new("Frame")\n	crossDot.Size = UDim2.new(0, 2, 0, 2)\n	crossDot.AnchorPoint = Vector2.new(0.5, 0.5)\n	crossDot.Position = UDim2.new(0.5, 0, 0.5, 0)\n	crossDot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)\n	crossDot.BorderSizePixel = 0\n	crossDot.Parent = crosshair\n\n	local crossUp = Instance.new("Frame")\n	crossUp.Size = UDim2.new(0, 1, 0, 6)\n	crossUp.AnchorPoint = Vector2.new(0.5, 1)\n	crossUp.Position = UDim2.new(0.5, 0, 0.5, -4)\n	crossUp.BackgroundColor3 = Color3.fromRGB(255, 255, 255)\n	crossUp.BorderSizePixel = 0\n	crossUp.Parent = crosshair\n\n	local crossDown = Instance.new("Frame")\n	crossDown.Size = UDim2.new(0, 1, 0, 6)\n	crossDown.AnchorPoint = Vector2.new(0.5, 0)\n	crossDown.Position = UDim2.new(0.5, 0, 0.5, 4)\n	crossDown.BackgroundColor3 = Color3.fromRGB(255, 255, 255)\n	crossDown.BorderSizePixel = 0\n	crossDown.Parent = crosshair\n\n	local crossLeft = Instance.new("Frame")\n	crossLeft.Size = UDim2.new(0, 6, 0, 1)\n	crossLeft.AnchorPoint = Vector2.new(1, 0.5)\n	crossLeft.Position = UDim2.new(0.5, -4, 0.5, 0)\n	crossLeft.BackgroundColor3 = Color3.fromRGB(255, 255, 255)\n	crossLeft.BorderSizePixel = 0\n	crossLeft.Parent = crosshair\n\n	local crossRight = Instance.new("Frame")\n	crossRight.Size = UDim2.new(0, 6, 0, 1)\n	crossRight.AnchorPoint = Vector2.new(0, 0.5)\n	crossRight.Position = UDim2.new(0.5, 4, 0.5, 0)\n	crossRight.BackgroundColor3 = Color3.fromRGB(255, 255, 255)\n	crossRight.BorderSizePixel = 0\n	crossRight.Parent = crosshair\n\n	local ammoFrame = Instance.new("Frame")\n	ammoFrame.Name = "AmmoDisplay"\n	ammoFrame.Size = UDim2.new(0, 160, 0, 50)\n	ammoFrame.Position = UDim2.new(1, -170, 1, -60)\n	ammoFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)\n	ammoFrame.BackgroundTransparency = 0.3\n	ammoFrame.Parent = screenGui\n\n	local ammoCorner = Instance.new("UICorner")\n	ammoCorner.CornerRadius = UDim.new(0, 8)\n	ammoCorner.Parent = ammoFrame\n\n	ammoLabel = Instance.new("TextLabel")\n	ammoLabel.Name = "Ammo"\n	ammoLabel.Size = UDim2.new(0.6, 0, 1, 0)\n	ammoLabel.Position = UDim2.new(0, 5, 0, 0)\n	ammoLabel.BackgroundTransparency = 1\n	ammoLabel.Text = "30"\n	ammoLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n	ammoLabel.Font = Enum.Font.GothamBlack\n	ammoLabel.TextSize = 32\n	ammoLabel.TextXAlignment = Enum.TextXAlignment.Left\n	ammoLabel.Parent = ammoFrame\n\n	reserveLabel = Instance.new("TextLabel")\n	reserveLabel.Name = "Reserve"\n	reserveLabel.Size = UDim2.new(0.35, 0, 1, 0)\n	reserveLabel.Position = UDim2.new(0.6, 0, 0, 0)\n	reserveLabel.BackgroundTransparency = 1\n	reserveLabel.Text = "/ 90"\n	reserveLabel.TextColor3 = Color3.fromRGB(150, 150, 150)\n	reserveLabel.Font = Enum.Font.Gotham\n	reserveLabel.TextSize = 18\n	reserveLabel.TextXAlignment = Enum.TextXAlignment.Left\n	reserveLabel.Parent = ammoFrame\n\n	ammoGui = screenGui\nend\n\nfunction WeaponClient:SetupInput()\n	UserInputService.InputBegan:Connect(function(input, processed)\n		if processed then return end\n\n		if input.UserInputType == Enum.UserInputType.MouseButton2 then\n			self:StartADS()\n		elseif input.UserInputType == Enum.UserInputType.MouseButton1 then\n			if not player:GetAttribute("EquippedWeapon") then return end\n			firing = true\n			if player:GetAttribute("EquippedWeaponAuto") then\n				task.spawn(function()\n					while firing do\n						Remotes.ShootWeapon:FireServer()\n						task.wait(0.05)\n					end\n				end)\n			end\n		elseif input.KeyCode == Enum.KeyCode.R then\n			Remotes.ReloadWeapon:FireServer()\n		end\n	end)\n\n	UserInputService.InputEnded:Connect(function(input, processed)\n		if input.UserInputType == Enum.UserInputType.MouseButton2 then\n			self:StopADS()\n		elseif input.UserInputType == Enum.UserInputType.MouseButton1 then\n			firing = false\n		end\n	end)\nend\n\nfunction WeaponClient:StartADS()\n	if isAiming then return end\n	if not player:GetAttribute("EquippedWeapon") then return end\n	if not isFirstPerson() then return end\n	isAiming = true\n\n	local tween = TweenService:Create(camera, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {\n		FieldOfView = adsFOV\n	})\n	tween:Play()\n\n	Remotes.StartADS:FireServer()\nend\n\nfunction WeaponClient:StopADS()\n	if not isAiming then return end\n	isAiming = false\n\n	local tween = TweenService:Create(camera, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {\n		FieldOfView = defaultFOV\n	})\n	tween:Play()\n\n	Remotes.StopADS:FireServer()\nend\n\nfunction WeaponClient:SetupRenderStep()\n	local ammoTimer = 0\n	RunService.RenderStepped:Connect(function(dt)\n		local weaponName = player:GetAttribute("EquippedWeapon")\n		if not weaponName then\n			if ammoGui then\n				ammoGui.Enabled = false\n			end\n			if crosshair then\n				crosshair.Visible = false\n			end\n			return\n		end\n\n		if ammoGui then\n			ammoGui.Enabled = true\n		end\n\n		if crosshair then\n			crosshair.Visible = isFirstPerson()\n		end\n\n		if isAiming and not isFirstPerson() then\n			self:StopADS()\n		end\n\n		recoilOffset = recoilOffset:Lerp(Vector3.new(), dt * 10)\n\n		ammoTimer += dt\n		if ammoTimer >= 0.2 and ammoLabel and reserveLabel then\n			ammoTimer = 0\n			local ok, ammo, reserve = pcall(function()\n				return Remotes.GetAmmo:InvokeServer()\n			end)\n			if ok and ammo then\n				ammoLabel.Text = tostring(ammo)\n				reserveLabel.Text = "/ " .. tostring(reserve)\n			end\n		end\n	end)\nend\n\nfunction WeaponClient:ApplyRecoil(vertical, horizontal)\n	recoilOffset += Vector3.new(horizontal, vertical, 0)\n	camera.CFrame = camera.CFrame * CFrame.Angles(\n		math.rad(-recoilOffset.Y),\n		math.rad(recoilOffset.X),\n		0\n	)\nend\n\nfunction WeaponClient:UpdateCrosshairSpread(spread)\n	local size = 20 + spread * 500\n	if crosshair then\n		crosshair.Size = UDim2.new(0, size, 0, size)\n	end\nend\n\nreturn WeaponClient\n')
ensureModule(SP:WaitForChild('StarterPlayerScripts'), 'Init', 'LocalScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal Players = game:GetService("Players")\n\nlocal player = Players.LocalPlayer\n\nlocal function waitForRemotes()\n	return ReplicatedStorage:WaitForChild("RemoteEvents", 30)\nend\n\nlocal function initModules()\n	local modules = ReplicatedStorage:WaitForChild("Modules", 30)\n	if not modules then return false end\n	return modules:WaitForChild("Config", 10) ~= nil\nend\n\nlocal function tryInit(name, fn)\n	local ok, err = pcall(fn)\n	if not ok then\n		warn(name .. " init failed: " .. tostring(err))\n	end\nend\n\ntask.spawn(function()\n	if not initModules() then\n		warn("Modules not loaded")\n		return\n	end\n\n	waitForRemotes()\n\n	tryInit("ClientController", function()\n		local clientController = require(player.PlayerScripts:WaitForChild("ClientController", 30))\n		if clientController and clientController.Init then\n			clientController:Init()\n		end\n	end)\n\n	tryInit("WeaponClient", function()\n		local weaponClient = require(player.PlayerScripts:WaitForChild("WeaponClient", 30))\n		if weaponClient and weaponClient.Init then\n			weaponClient:Init()\n		end\n	end)\n\n	tryInit("MainMenu", function()\n		local mainMenu = require(player.PlayerGui:WaitForChild("MainMenu"):WaitForChild("MainMenuClient", 30))\n		if mainMenu and mainMenu.Start then\n			mainMenu:Start()\n		end\n	end)\nend)\n')
ensureModule(SG:WaitForChild('MainMenu'), 'MainMenuClient', 'ModuleScript', 'local Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal TweenService = game:GetService("TweenService")\nlocal SoundService = game:GetService("SoundService")\n\nlocal Config = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Config"))\nlocal Remotes = ReplicatedStorage:WaitForChild("RemoteEvents")\n\nlocal player = Players.LocalPlayer\nlocal playerGui = player:WaitForChild("PlayerGui")\n\nlocal MainMenu = {}\nMainMenu.__index = MainMenu\n\nlocal LOADING_STAGES = {\n	"Загрузка ассетов",\n	"Прогрузка карты",\n	"Инициализация систем",\n	"Подключение к серверу",\n	"Готово",\n}\n\nfunction MainMenu:CreateLoadingScreen()\n	local screenGui = Instance.new("ScreenGui")\n	screenGui.Name = "LoadingScreen"\n	screenGui.IgnoreGuiInset = true\n	screenGui.DisplayOrder = 100\n	screenGui.Parent = playerGui\n\n	local bg = Instance.new("Frame")\n	bg.Size = UDim2.new(1, 0, 1, 0)\n	bg.BackgroundColor3 = Color3.fromRGB(10, 10, 10)\n	bg.BorderSizePixel = 0\n	bg.Parent = screenGui\n\n	local logo = Instance.new("ImageLabel")\n	logo.Size = UDim2.new(0, 200, 0, 200)\n	logo.Position = UDim2.new(0.5, -100, 0.3, -100)\n	logo.BackgroundTransparency = 1\n	logo.Image = "rbxassetid://0"\n	logo.Parent = bg\n\n	local titleLabel = Instance.new("TextLabel")\n	titleLabel.Size = UDim2.new(1, 0, 0, 60)\n	titleLabel.Position = UDim2.new(0, 0, 0.5, 10)\n	titleLabel.BackgroundTransparency = 1\n	titleLabel.Text = "SFKU.inc"\n	titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n	titleLabel.Font = Enum.Font.GothamBlack\n	titleLabel.TextSize = 48\n	titleLabel.Parent = bg\n\n	local progressFrame = Instance.new("Frame")\n	progressFrame.Size = UDim2.new(0.6, 0, 0, 4)\n	progressFrame.Position = UDim2.new(0.2, 0, 0.7, 0)\n	progressFrame.BackgroundColor3 = Color3.fromRGB(50, 50, 50)\n	progressFrame.BorderSizePixel = 0\n	progressFrame.Parent = bg\n\n	local progressFill = Instance.new("Frame")\n	progressFill.Size = UDim2.new(0, 0, 1, 0)\n	progressFill.BackgroundColor3 = Color3.fromRGB(255, 255, 255)\n	progressFill.BorderSizePixel = 0\n	progressFill.Parent = progressFrame\n\n	local statusLabel = Instance.new("TextLabel")\n	statusLabel.Size = UDim2.new(1, 0, 0, 30)\n	statusLabel.Position = UDim2.new(0, 0, 0.7, 15)\n	statusLabel.BackgroundTransparency = 1\n	statusLabel.Text = LOADING_STAGES[1]\n	statusLabel.TextColor3 = Color3.fromRGB(180, 180, 180)\n	statusLabel.Font = Enum.Font.Gotham\n	statusLabel.TextSize = 16\n	statusLabel.Parent = bg\n\n	for i, stage in ipairs(LOADING_STAGES) do\n		statusLabel.Text = stage\n		local tween = TweenService:Create(progressFill, TweenInfo.new(0.5, Enum.EasingStyle.Linear), {\n			Size = UDim2.new(i / #LOADING_STAGES, 0, 1, 0)\n		})\n		tween:Play()\n		tween.Completed:Wait()\n		task.wait(0.3)\n	end\n\n	local fadeOut = TweenService:Create(bg, TweenInfo.new(0.5, Enum.EasingStyle.Linear), {\n		BackgroundTransparency = 1,\n	})\n	for _, desc in ipairs(bg:GetDescendants()) do\n		if desc:IsA("TextLabel") then\n			TweenService:Create(desc, TweenInfo.new(0.5, Enum.EasingStyle.Linear), {\n				BackgroundTransparency = 1,\n				TextTransparency = 1,\n			}):Play()\n		elseif desc:IsA("ImageLabel") then\n			TweenService:Create(desc, TweenInfo.new(0.5, Enum.EasingStyle.Linear), {\n				BackgroundTransparency = 1,\n				ImageTransparency = 1,\n			}):Play()\n		elseif desc:IsA("Frame") then\n			TweenService:Create(desc, TweenInfo.new(0.5, Enum.EasingStyle.Linear), {\n				BackgroundTransparency = 1,\n			}):Play()\n		end\n	end\n	fadeOut:Play()\n	fadeOut.Completed:Wait()\n\n	screenGui:Destroy()\nend\n\nfunction MainMenu:CreateMainMenu()\n	local screenGui = Instance.new("ScreenGui")\n	screenGui.Name = "MainMenu"\n	screenGui.IgnoreGuiInset = true\n	screenGui.DisplayOrder = 99\n	screenGui.Parent = playerGui\n\n	local bg = Instance.new("Frame")\n	bg.Size = UDim2.new(1, 0, 1, 0)\n	bg.BackgroundColor3 = Color3.fromRGB(10, 10, 10)\n	bg.BorderSizePixel = 0\n	bg.Parent = screenGui\n\n	local titleLabel = Instance.new("TextLabel")\n	titleLabel.Size = UDim2.new(1, 0, 0, 60)\n	titleLabel.Position = UDim2.new(0, 0, 0.15, 0)\n	titleLabel.BackgroundTransparency = 1\n	titleLabel.Text = "SFKU.inc"\n	titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n	titleLabel.Font = Enum.Font.GothamBlack\n	titleLabel.TextSize = 56\n	titleLabel.Parent = bg\n\n	local function createMenuButton(text, position, callback)\n		local btn = Instance.new("TextButton")\n		btn.Size = UDim2.new(0, 280, 0, 50)\n		btn.Position = position\n		btn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)\n		btn.TextColor3 = Color3.fromRGB(255, 255, 255)\n		btn.Text = text\n		btn.Font = Enum.Font.GothamBold\n		btn.TextSize = 20\n		btn.BorderSizePixel = 0\n		btn.Parent = bg\n\n		local corner = Instance.new("UICorner")\n		corner.CornerRadius = UDim.new(0, 8)\n		corner.Parent = btn\n\n		btn.MouseEnter:Connect(function()\n			TweenService:Create(btn, TweenInfo.new(0.2), {\n				BackgroundColor3 = Color3.fromRGB(50, 50, 50),\n				Size = UDim2.new(0, 290, 0, 52),\n			}):Play()\n		end)\n\n		btn.MouseLeave:Connect(function()\n			TweenService:Create(btn, TweenInfo.new(0.2), {\n				BackgroundColor3 = Color3.fromRGB(30, 30, 30),\n				Size = UDim2.new(0, 280, 0, 50),\n			}):Play()\n		end)\n\n		btn.MouseButton1Click:Connect(function()\n			callback()\n		end)\n\n		return btn\n	end\n\n	local mainButtons = Instance.new("Frame")\n	mainButtons.Name = "MainButtons"\n	mainButtons.Size = UDim2.new(1, 0, 1, 0)\n	mainButtons.BackgroundTransparency = 1\n	mainButtons.Parent = bg\n\n	createMenuButton("Играть", UDim2.new(0.5, -140, 0.4, 0), function()\n		TweenService:Create(bg, TweenInfo.new(0.5), {BackgroundTransparency = 1}):Play()\n		for _, desc in ipairs(bg:GetDescendants()) do\n			if desc:IsA("TextLabel") or desc:IsA("TextButton") then\n				TweenService:Create(desc, TweenInfo.new(0.5), {TextTransparency = 1, BackgroundTransparency = 1}):Play()\n			end\n		end\n		task.wait(0.5)\n		screenGui:Destroy()\n	end)\n\n	createMenuButton("Выбор роли", UDim2.new(0.5, -140, 0.4, 70), function()\n		self:OpenRoleSelection(screenGui, bg)\n	end)\n\n	createMenuButton("Разработчики", UDim2.new(0.5, -140, 0.4, 140), function()\n		self:OpenDevelopers(screenGui, bg)\n	end)\nend\n\nfunction MainMenu:OpenRoleSelection(parentGui, mainBg)\n	local roleFrame = Instance.new("Frame")\n	roleFrame.Name = "RoleSelection"\n	roleFrame.Size = UDim2.new(0.8, 0, 0.7, 0)\n	roleFrame.Position = UDim2.new(0.1, 0, 0.15, 0)\n	roleFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)\n	roleFrame.BorderSizePixel = 0\n	roleFrame.Parent = parentGui\n\n	local corner = Instance.new("UICorner")\n	corner.CornerRadius = UDim.new(0, 12)\n	corner.Parent = roleFrame\n\n	local title = Instance.new("TextLabel")\n	title.Size = UDim2.new(1, 0, 0, 40)\n	title.BackgroundTransparency = 1\n	title.Text = "Выбор роли"\n	title.TextColor3 = Color3.fromRGB(255, 255, 255)\n	title.Font = Enum.Font.GothamBold\n	title.TextSize = 24\n	title.Parent = roleFrame\n\n	local tabsFrame = Instance.new("Frame")\n	tabsFrame.Size = UDim2.new(1, 0, 0, 40)\n	tabsFrame.Position = UDim2.new(0, 0, 0, 45)\n	tabsFrame.BackgroundTransparency = 1\n	tabsFrame.Parent = roleFrame\n\n	local tabsLayout = Instance.new("UIListLayout")\n	tabsLayout.FillDirection = Enum.FillDirection.Horizontal\n	tabsLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n	tabsLayout.Padding = UDim.new(0, 10)\n	tabsLayout.Parent = tabsFrame\n\n	local contentFrame = Instance.new("ScrollingFrame")\n	contentFrame.Name = "Content"\n	contentFrame.Size = UDim2.new(1, -20, 1, -100)\n	contentFrame.Position = UDim2.new(0, 10, 0, 95)\n	contentFrame.BackgroundTransparency = 1\n	contentFrame.ScrollBarThickness = 6\n	contentFrame.Parent = roleFrame\n\n	local contentLayout = Instance.new("UIListLayout")\n	contentLayout.Padding = UDim.new(0, 6)\n	contentLayout.Parent = contentFrame\n\n	local function switchTab(tabName)\n		for _, child in ipairs(contentFrame:GetChildren()) do\n			if child:IsA("GuiObject") then\n				child:Destroy()\n			end\n		end\n\n		if tabName == "minutes" then\n			local roles = Remotes.GetAvailableRoles:InvokeServer()\n			if roles and roles.minuteRoles then\n				for _, role in ipairs(roles.minuteRoles) do\n					local roleBtn = Instance.new("TextButton")\n					roleBtn.Size = UDim2.new(1, 0, 0, 35)\n					roleBtn.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\n					roleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\n					roleBtn.Text = role.displayName .. " | " .. role.requiredMinutes .. " мин"\n					roleBtn.Font = Enum.Font.Gotham\n					roleBtn.TextSize = 14\n					roleBtn.Parent = contentFrame\n\n					local btnCorner = Instance.new("UICorner")\n					btnCorner.CornerRadius = UDim.new(0, 6)\n					btnCorner.Parent = roleBtn\n\n					roleBtn.MouseButton1Click:Connect(function()\n						Remotes.SelectRole:InvokeServer(role.id)\n					end)\n				end\n			end\n		elseif tabName == "faction" then\n			local roles = Remotes.GetAvailableRoles:InvokeServer()\n			if roles and roles.factionRoles then\n				for _, role in ipairs(roles.factionRoles) do\n					local roleBtn = Instance.new("TextButton")\n					roleBtn.Size = UDim2.new(1, 0, 0, 35)\n					roleBtn.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\n					roleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\n					roleBtn.Text = role.displayName .. " | " .. role.faction\n					roleBtn.Font = Enum.Font.Gotham\n					roleBtn.TextSize = 14\n					roleBtn.Parent = contentFrame\n\n					local btnCorner = Instance.new("UICorner")\n					btnCorner.CornerRadius = UDim.new(0, 6)\n					btnCorner.Parent = roleBtn\n\n					roleBtn.MouseButton1Click:Connect(function()\n						Remotes.SelectFactionRole:InvokeServer(role.id)\n					end)\n				end\n			end\n		elseif tabName == "project" then\n			local label = Instance.new("TextLabel")\n			label.Size = UDim2.new(1, 0, 0, 30)\n			label.BackgroundTransparency = 1\n			label.Text = "Роли руководства доступны только для администрации"\n			label.TextColor3 = Color3.fromRGB(150, 150, 150)\n			label.Font = Enum.Font.Gotham\n			label.TextSize = 14\n			label.Parent = contentFrame\n		end\n\n		contentFrame.CanvasSize = UDim2.new(0, 0, 0, contentLayout.AbsoluteContentSize.Y)\n	end\n\n	local function createTab(text, tabName)\n		local tab = Instance.new("TextButton")\n		tab.Size = UDim2.new(0, 150, 0, 35)\n		tab.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\n		tab.TextColor3 = Color3.fromRGB(200, 200, 200)\n		tab.Text = text\n		tab.Font = Enum.Font.Gotham\n		tab.TextSize = 14\n		tab.Parent = tabsFrame\n\n		local tabCorner = Instance.new("UICorner")\n		tabCorner.CornerRadius = UDim.new(0, 6)\n		tabCorner.Parent = tab\n\n		tab.MouseButton1Click:Connect(function()\n			switchTab(tabName)\n		end)\n\n		return tab\n	end\n\n	createTab("Роли за минуты", "minutes")\n	createTab("Фракционные роли", "faction")\n	createTab("Роли руководства", "project")\n\n	local closeBtn = Instance.new("TextButton")\n	closeBtn.Size = UDim2.new(0, 100, 0, 30)\n	closeBtn.Position = UDim2.new(1, -110, 0, 5)\n	closeBtn.BackgroundColor3 = Color3.fromRGB(150, 0, 0)\n	closeBtn.TextColor3 = Color3.fromRGB(255, 255, 255)\n	closeBtn.Text = "Назад"\n	closeBtn.Font = Enum.Font.GothamBold\n	closeBtn.TextSize = 14\n	closeBtn.Parent = roleFrame\n\n	local closeCorner = Instance.new("UICorner")\n	closeCorner.CornerRadius = UDim.new(0, 6)\n	closeCorner.Parent = closeBtn\n\n	closeBtn.MouseButton1Click:Connect(function()\n		roleFrame:Destroy()\n	end)\n\n	switchTab("minutes")\nend\n\nfunction MainMenu:OpenDevelopers(parentGui, mainBg)\n	local devFrame = Instance.new("Frame")\n	devFrame.Name = "Developers"\n	devFrame.Size = UDim2.new(0.7, 0, 0.6, 0)\n	devFrame.Position = UDim2.new(0.15, 0, 0.2, 0)\n	devFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)\n	devFrame.BorderSizePixel = 0\n	devFrame.Parent = parentGui\n\n	local corner = Instance.new("UICorner")\n	corner.CornerRadius = UDim.new(0, 12)\n	corner.Parent = devFrame\n\n	local title = Instance.new("TextLabel")\n	title.Size = UDim2.